import{_ as e,o,c as a,a2 as r}from"./chunks/framework.Dxeykp0S.js";const u=JSON.parse('{"title":"Day 5 · pytest：写出让同事羡慕的测试","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/05-testing.md","filePath":"advanced/05-testing.md","lastUpdated":1787141678000}'),d={name:"advanced/05-testing.md"};function i(c,t,s,l,n,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="day-5-·-pytest-写出让同事羡慕的测试" tabindex="-1">Day 5 · pytest：写出让同事羡慕的测试 <a class="header-anchor" href="#day-5-·-pytest-写出让同事羡慕的测试" aria-label="Permalink to &quot;Day 5 · pytest：写出让同事羡慕的测试&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>pytest 使用 Python 原生 <code>assert</code> 编写断言，并通过 <strong>fixture</strong> 这套依赖注入机制管理测试资源。今天我们从第一个测试用例开始，逐步掌握 fixture、参数化与 mock。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>掌握 pytest 基础：发现规则、断言、参数化</li><li>精通 fixture：作用域、组合、conftest.py</li><li>掌握 monkeypatch 与 mock</li><li>会用 httpx + pytest 测试 FastAPI 应用</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.pytest.org/" target="_blank" rel="noreferrer">pytest 官方文档</a>（重点：fixtures、parametrize）</li><li><a href="https://fastapi.tiangolo.com/zh/tutorial/testing/" target="_blank" rel="noreferrer">FastAPI 官方：Testing</a></li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>Vitest/Jest</th><th>pytest</th></tr></thead><tbody><tr><td><code>describe</code> / <code>it</code></td><td>普通函数 <code>def test_xxx()</code>（类可选）</td></tr><tr><td><code>expect(a).toBe(b)</code></td><td><code>assert a == b</code>（原生断言，报错信息更强大）</td></tr><tr><td><code>beforeEach</code> / <code>afterEach</code></td><td>fixture（function 作用域）</td></tr><tr><td><code>beforeAll</code> / <code>afterAll</code></td><td>fixture（scope=&quot;module&quot;/&quot;session&quot;）</td></tr><tr><td><code>test.each</code></td><td><code>@pytest.mark.parametrize</code></td></tr><tr><td><code>vi.fn()</code> / <code>vi.spyOn</code></td><td><code>unittest.mock</code> / <code>pytest-mock</code> 的 mocker</td></tr><tr><td><code>vi.stubGlobal</code></td><td><code>monkeypatch</code> fixture</td></tr><tr><td>快照测试</td><td><code>pytest-snapshot</code>（小众）</td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><p><strong>给 FastAPI 项目补测试</strong>：用 <code>fastapi.testclient.TestClient</code> 为 Day 4 的任务管理 API 写测试套件，覆盖：</p><ul><li>创建任务的 happy path 与 422 校验失败</li><li>CRUD 全流程</li><li>过滤与分页</li><li>未认证的 401</li></ul></li><li><p><strong>fixture 进阶</strong>：实现一个 <code>db</code> fixture（scope=&quot;function&quot;），每个测试前初始化内存存储、测试后清空；再实现一个 <code>client</code> fixture 依赖 <code>db</code>，体会 fixture 的依赖注入与生命周期管理。</p></li><li><p><strong>参数化测试</strong>：用 <code>@pytest.mark.parametrize</code> 为&quot;title 长度校验&quot;写 10 组边界用例（空串、1 字符、100 字符、101 字符、纯空格……），一个函数跑完所有用例。</p></li><li><p><strong>mock 外部依赖</strong>：假设 API 中有个接口调用外部天气服务，用 <code>pytest-mock</code> 的 <code>mocker.patch</code> 或 <code>monkeypatch</code> 将其替换为假实现，测试&quot;外部服务超时时返回降级响应&quot;的逻辑。</p></li><li><p><strong>配置 pytest</strong>：在 <code>pyproject.toml</code> 中配置 <code>[tool.pytest.ini_options]</code>：testpaths、strict markers、覆盖率插件（<code>pytest-cov</code>），目标覆盖率 ≥ 80%。</p></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li>fixture 的 scope 如何影响创建、复用与清理时机？</li><li>fixture 的 function/module/session 作用域分别适合什么资源？</li><li><code>conftest.py</code> 的作用是什么？它的 fixture 如何被发现？</li><li><code>monkeypatch</code> 和 <code>unittest.mock.patch</code> 的区别与适用场景？</li><li>pytest 如何做到 <code>assert a == b</code> 失败时显示详细的差异信息？（提示：断言重写）</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://docs.pytest.org/en/stable/explanation/goodpractices.html" target="_blank" rel="noreferrer">pytest 官方：Good Integration Practices</a></li><li><a href="https://github.com/pytest-dev/pytest-asyncio" target="_blank" rel="noreferrer">pytest-asyncio</a> —— 测试 async 路由必备</li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>进阶班通关！下一站<a href="/python-practices/pro/">高级班</a>：继续学习 ORM、认证、队列、缓存、Docker 与 K8s，建立完整的 Python 后端工程能力。</p>',18)])])}const f=e(d,[["render",i]]);export{u as __pageData,f as default};
